import { version } from "./version.mjs";

// Generated by scripts/gen-icons.mjs into public/, which the build copies verbatim.
const icons = {
  16: "icons/icon-16.png",
  32: "icons/icon-32.png",
  48: "icons/icon-48.png",
  128: "icons/icon-128.png",
};

const base = {
  manifest_version: 3,
  name: "Colorway",
  version,
  description: "Recolors picked elements of any site and marks the tab so instances are told apart",
  icons,
  // No "tabs": the panel frame reads the active tab through activeTab (granted by the
  // action click that injects it) and the host permissions of sites the user has
  // already configured.
  permissions: ["storage", "scripting", "activeTab"],
  optional_host_permissions: ["*://*/*"],
  action: { default_title: "Colorway", default_icon: icons },
  options_ui: { page: "options.html", open_in_tab: true },
  // panel.html is loaded in an iframe injected into the clicked page, on any
  // site — not just ones the extension has host permission for — so it must be
  // reachable from every origin rather than none.
  web_accessible_resources: [{ resources: ["panel.html"], matches: ["<all_urls>"] }],
};

const overrides = {
  chrome: {
    background: { service_worker: "background.js" },
    // structuredClone (settingsRepo.ts) needs Chrome 98, already above what the MV3
    // web_accessible_resources object form above requires (96) — but
    // optional_host_permissions, used above, is the real floor: it shipped in
    // Chrome 102, and nothing else here needs the 116 the side panel used to.
    minimum_chrome_version: "102",
  },
  firefox: {
    background: { scripts: ["background.js"] },
    browser_specific_settings: {
      gecko: {
        id: "colorway@arturminchukov",
        // 140 is where data_collection_permissions below became readable, and the floor
        // is set to match it rather than to the oldest Firefox the code would run on:
        // an ESR that ignores the key is an ESR that cannot honour the consent it
        // declares. Nothing is lost by it — 128 ESR is end-of-life, and the live ESR
        // branches (140, 153) are both at or above this floor.
        strict_min_version: "140.0",
        // Required by AMO for new extensions. Nothing is collected: every profile stays
        // in browser.storage.local on the device (see PRIVACY.md).
        //
        // web-ext lint still warns that Firefox for Android only learned this key in
        // 142. That warning is noise here: with no gecko_android sub-key the add-on is
        // listed for desktop Firefox only, so the Android floor it computes applies to
        // a platform this extension is never installed on. Adding gecko_android to
        // silence it would opt into Android — the opposite of what the omission means.
        data_collection_permissions: { required: ["none"] },
      },
    },
  },
};

export function buildManifest(target) {
  const override = overrides[target];
  if (!override) throw new Error(`unknown target: ${target}`);
  return { ...base, ...override };
}
